const HTML_ENDPOINT = "http://127.0.0.1:8000/api/v1/users/preview";

const fetchBtn = document.getElementById("load-users-btn");
const output = document.getElementById("content-output");

fetchBtn.addEventListener("click", async () => {
  output.textContent = "Connecting to API...";

  try {
    const response = await fetch(HTML_ENDPOINT);

    if (!response.ok) {
      throw new Error(`HTTP error! status: ${response.status}`);
    }

    // This endpoint returns trusted HTML generated by the backend.
    output.innerHTML = await response.text();
  } catch (error) {
    output.textContent = `Connection failed: ${error.message}`;
  }
});
